INSERT INTO "public"."TermsAndConditions" ("id", "name", "html_content", "created_at", "created_by_user_uuid", "deleted") VALUES
	('f0a10001-0001-4000-8000-000000000001', 'Standard Rental Terms', '<h2>Standard Terms &amp; Conditions</h2><p>1. <strong>Payment:</strong> A 50% deposit is required upon booking. The remaining balance is due 7 days before the event start date.</p><p>2. <strong>Cancellation:</strong> Cancellations made 30+ days before the event receive a full refund minus a $250 processing fee. Cancellations within 30 days forfeit the deposit.</p><p>3. <strong>Delivery &amp; Setup:</strong> Bleacher Rentals will deliver and set up equipment at the agreed-upon location. The client must ensure the site is accessible and level.</p><p>4. <strong>Liability:</strong> The client is responsible for any damage to equipment during the rental period beyond normal wear and tear.</p><p>5. <strong>Insurance:</strong> The client must provide proof of general liability insurance with a minimum of $1,000,000 coverage naming Bleacher Rentals as additionally insured.</p>', '2026-06-18 22:21:41.789948+00', '5847580c-471a-481e-92f7-582e7441eff4', false),
	('f0a10001-0001-4000-8000-000000000002', 'Short-Term Rental Terms', '<h2>Short-Term Rental Terms</h2><p>1. <strong>Payment:</strong> Full payment is due upon delivery for rentals under 3 days.</p><p>2. <strong>Cancellation:</strong> Cancellations made 14+ days before the event receive a full refund. No refunds within 14 days.</p><p>3. <strong>Delivery &amp; Pickup:</strong> Delivery and pickup times will be coordinated in advance. Additional charges apply for after-hours service.</p><p>4. <strong>Liability:</strong> The client assumes full responsibility for the equipment from delivery to pickup.</p>', '2026-06-18 22:21:41.789948+00', '5847580c-471a-481e-92f7-582e7441eff4', false);
