	('fac8721f-5440-40e6-8fe1-f6e8eb88b24e', '42fedbbd-2d36-41c0-ad6b-bbe4b8a4d3ed', NULL, 'Alert - Event Requirements are not met', '<p>this compares number of seats, rows, bleachers, etc. with the bleachers that have been selected.</p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-05 12:47:21.069+00', '2026-05-07 19:01:15.922975+00', NULL),
	('7598e078-46d4-43ff-864b-27be5b023efa', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Setup Accounting Meeting With Max', '<p></p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-08 17:40:09.751+00', '2026-05-19 18:24:24.032323+00', NULL),
